e=html.escape
def write(path,text):
    p=OUT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
def page(path,title,description,body,schema=None):
    url=BASE+('/' if path=='index.html' else '/'+path.replace('index.html',''))
    data={'@context':'https://schema.org','@type':'Organization','name':'Trailwise Gear','url':BASE} if schema is None else schema
    write(path,f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="google-site-verification" content="1MeKjoKHpi5pSPYf6qovnzJHeW9wuBDJeyeqPOC2RTk"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Trailwise Gear</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta name="theme-color" content="#183f35"><link rel="stylesheet" href="/style.css"><link rel="icon" href="/icon.svg" type="image/svg+xml"><script type="application/ld+json">{json.dumps(data)}</script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/" aria-label="Trailwise Gear home"><span class="mark" aria-hidden="true">△</span> TRAILWISE <span>GEAR</span></a><nav aria-label="Main navigation"><a href="/guides/">All guides</a><a href="/comparisons/">Compare gear</a><a href="/about/">About</a></nav></header><main id="main">{body}</main><footer><div><a class="brand" href="/">TRAILWISE GEAR</a><p>Go farther. Spend smarter.</p><p>Independent research. Practical tradeoffs. No invented tests.</p></div><nav aria-label="Publication policies"><a href="/contact/">Contact & corrections</a><a href="/editorial-policy/">Editorial policy</a><a href="/affiliate-disclosure/">Affiliate disclosure</a><a href="/privacy/">Privacy</a><a href="/sitemap.xml">Sitemap</a></nav><p class="fine">© 2026 Trailwise Gear. Some guides include disclosed affiliate links; we may earn a commission on qualifying purchases. Conditions and equipment change; check current instructions before a trip.</p></footer><!-- Cloudflare Web Analytics --><script type='module' src='https://static.cloudflareinsights.com/beacon.min.js' data-cf-beacon='{{"token": "bf99e6384e404a42ab00d264a79358c6"}}'></script><!-- End Cloudflare Web Analytics --></body></html>''')
def inline(text):
    """Escape content, then render the small supported Markdown subset."""
    safe=e(text)
    def link(m):
        rel='sponsored external' if m[2].startswith(('https://bougerv.sjv.io/', 'https://www.dpbolvw.net/', 'https://www.tkqlhce.com/')) else 'external'
        return f'<a href="{m[2]}" rel="{rel}">{m[1]}</a>'
    safe=re.sub(r'\[([^\]]+)\]\((https://[^\s)]+)\)',link,safe)
    return re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',safe)

def card(g):
    return f'<article class="card"><p class="eyebrow">{e(g["category"])}</p><h3><a href="/guides/{g["slug"]}/">{e(g["title"])}</a></h3><p>{e(g["description"])}</p><span class="fine">Research-based guide · Read guide →</span></article>'
def cards(items):return '<div class="grid">'+''.join(card(g) for g in items)+'</div>'
page('index.html','Practical gear advice for affordable adventures','Budget-first camping and trail guides. Clear comparisons, useful checklists, and honest research without invented product testing.',f'''<section class="hero"><div><p class="eyebrow">LESS HYPE. MORE OUTSIDE.</p><h1>Good adventures.<br>Smarter gear choices.</h1><p class="lede">Spend on what helps. Skip what doesn't. Practical guides for your first campsite, next trail day, and everything you carry along.</p><a class="button" href="/guides/first-car-camping-trip/">Plan your first camping trip <span aria-hidden="true">↗</span></a><a class="text-link" href="/comparisons/">Compare before you buy →</a></div><div class="landscape" aria-hidden="true"><span class="sun"></span><span class="ridge back"></span><span class="ridge front"></span><span class="trail"></span><span class="caption">THE OUTSIDE IS FOR EVERYONE.</span></div></section><div class="trust"><span>Budget comes first</span><span>Sources you can check</span><span>Research clearly labeled</span></div><section id="guides"><div class="section-head"><div><p class="eyebrow">YOUR STARTING POINT</p><h2>Buy less. Know more.</h2></div><a href="/guides/">Explore all 10 guides →</a></div>{cards(guides[:3])}</section><section class="feature"><p class="eyebrow">THE COMPLETE KIT MATTERS</p><h2>A cheap burner isn't always a cheap kitchen.</h2><p>Compare the pot, fuel, accessories, and meals—not just the price on the box.</p><a class="button light" href="/guides/pocketrocket-2-vs-jetboil-flash/">PocketRocket 2 vs Jetboil Flash →</a></section><section><div class="section-head"><div><p class="eyebrow">VEHICLE & TRAIL</p><h2>Prepare before you upgrade.</h2></div></div>{cards(guides[-3:])}</section><section id="off-road-upgrades"><div class="section-head"><div><p class="eyebrow">BUDGET OFF-ROAD UPGRADES</p><h2>Research your next truck upgrade.</h2></div></div><p>Browse KSP Performance categories below. These are shopping options, not hands-on product reviews or confirmed fitment recommendations for any specific truck.</p><p class="fine"><strong>Affiliate disclosure:</strong> These are paid affiliate links. Trailwise Gear may earn a commission on qualifying purchases at no additional cost to you.</p><div class="grid"><article class="card"><p class="eyebrow">KSP Performance</p><h3>Wheel spacers</h3><p>Compare spacer dimensions, hub fit, hardware, and vehicle compatibility before ordering.</p><a href="https://www.dpbolvw.net/click-101916053-17167892" rel="sponsored noopener noreferrer" target="_blank">Browse wheel spacers →</a></article><article class="card"><p class="eyebrow">KSP Performance</p><h3>Leveling lift kits</h3><p>Research lift geometry, alignment needs, and vehicle-specific installation requirements.</p><a href="https://www.anrdoezrs.net/click-101916053-17167895" rel="sponsored noopener noreferrer" target="_blank">Browse leveling lift kits →</a></article><article class="card"><p class="eyebrow">KSP Performance</p><h3>Aluminum control arms</h3><p>Explore suspension component options; confirm exact fitment and intended use.</p><a href="https://www.jdoqocy.com/click-101916053-17167893" rel="sponsored noopener noreferrer" target="_blank">Browse aluminum control arms →</a></article><article class="card"><p class="eyebrow">KSP Performance</p><h3>Control arms</h3><p>Browse replacement and upgrade options matched to your vehicle.</p><a href="https://www.tkqlhce.com/click-101916053-17167894" rel="sponsored noopener noreferrer" target="_blank">Browse control arms →</a></article></div><p class="fine">Check vehicle year, drivetrain, bolt pattern, fitment, safety instructions, and seller specifications before purchasing. No KSP products have been independently tested by Trailwise Gear.</p></section><section id="portable-camp-power"><div class="section-head"><div><p class="eyebrow">CAMP POWER OPTIONS</p><h2>Explore portable power for your next campsite.</h2></div></div><p>ALLPOWERS offers portable power stations and solar charging options for drive-up camping and off-grid setups. Compare capacity in watt-hours, output ports, weight, charging methods and the power requirements of the devices you actually bring. A larger station may be unnecessary for a short trip.</p><p class="fine"><strong>Affiliate disclosure:</strong> The ALLPOWERS shopping links below are tracked affiliate links. Trailwise Gear may earn a commission on qualifying purchases at no additional cost to you.</p><div class="grid"><article class="card"><p class="eyebrow">ALLPOWERS · Official Store</p><h3>Browse the full US store</h3><p>Compare power stations and other solar power equipment, and confirm current prices, warranty and product specifications with the manufacturer. This is not a hands-on review.</p><a href="https://www.anrdoezrs.net/click-101916053-17222097" rel="sponsored noopener noreferrer" target="_blank">Shop ALLPOWERS →</a></article><article class="card"><p class="eyebrow">ALLPOWERS · Portable Power</p><h3>Portable power stations</h3><p>Compare battery capacities, output and charging options for your actual campsite needs before choosing a model.</p><a href="https://www.tkqlhce.com/click-101916053-17222100" rel="sponsored noopener noreferrer" target="_blank">Browse portable power stations →</a></article><article class="card"><p class="eyebrow">Trailwise Gear guide</p><h3>How much camp power do you need?</h3><p>Start with a watt-hour budget before investing in a portable power station.</p><a href="/guides/camping-power-bank-sizing/">Read our power sizing guide →</a></article></div><p class="fine">These product categories are for comparison; no ALLPOWERS products have been independently tested by Trailwise Gear.</p></section><section class="about-strip"><h2>Advice with the limits left in.</h2><p>We explain what the evidence supports, where the tradeoffs are, and when you may not need to buy anything at all. These initial guides are desk-researched, with no claim of hands-on testing.</p><a href="/editorial-policy/">How our guides are made →</a></section>''')
page('guides/index.html','Camping and trail guides','Browse practical camping, cooking, vehicle, and gear-buying guides.','<div class="page-intro"><p class="eyebrow">THE GUIDEBOOK</p><h1>A little planning goes a long way.</h1><p>Choose a real problem to solve, then find the equipment that fits.</p></div>'+cards(guides))
page('comparisons/index.html','Research-based gear comparisons','Compare complete systems and practical tradeoffs before buying outdoor gear.','<div class="page-intro"><p class="eyebrow">BEFORE YOU BUY</p><h1>Compare the tradeoffs.</h1><p>Research-based comparisons. No lab scores, purchased rankings, or claims of personal testing.</p></div>'+cards([g for g in guides if g['category']=='Gear comparisons']))
for g in guides:
    updated = g.get('updated')
    update_note = f' · Updated {e(updated)}' if updated else ''
    toc='<nav class="toc" aria-label="In this guide"><strong>In this guide</strong><ol>'+''.join(f'<li><a href="#section-{i}">{e(s[0])}</a></li>' for i,s in enumerate(g['sections']))+'</ol></nav>'
    body=f'<div class="article-head"><a href="/guides/">← All guides</a><p class="eyebrow">{e(g["category"])}</p><h1>{e(g["title"])}</h1><p class="lede">{e(g["description"])}</p><p class="fine">By Trailwise Gear editorial desk · Published and source-checked October 26, 2026 · Desk research{update_note}</p></div><div class="article-layout">{toc}<article class="prose"><aside class="answer"><strong>The practical answer</strong><p>{e(g["answer"])}</p></aside>'
    for i,(heading,text) in enumerate(g['sections']):
        body+=f'<section id="section-{i}"><h2>{e(heading)}</h2>'+''.join(f'<p>{inline(p)}</p>' for p in text.split('\n'))+'</section>'
    source_note = g.get("source_note", 'Manufacturer specifications and source guidance were checked on October 26, 2026. Buying recommendations are our editorial judgments. We have not tested these products.')
    body+='<section class="sources"><h2>Sources & evidence</h2><p>'+e(source_note)+'</p><ul>'+''.join(f'<li><a href="{e(url)}" rel="external">{e(label)}</a></li>' for label,url in g['sources'])+'</ul><p>Source references are ordinary links. Any commercial links are identified near the recommendation. <a href="/contact/">Report a correction</a>.</p></section></article></div><section><h2>Keep planning</h2>'+cards([next(x for x in guides if x['slug']==slug) for slug in g['related']])+'</section>'
    schema={'@context':'https://schema.org','@type':'Article','headline':g['title'],'description':g['description'],'datePublished':DATE,'dateModified':g.get('updated',DATE),'author':{'@type':'Organization','name':'Trailwise Gear editorial desk'},'publisher':{'@type':'Organization','name':'Trailwise Gear'},'mainEntityOfPage':BASE+'/guides/'+g['slug']+'/','citation':[s[1] for s in g['sources']]}
    page('guides/'+g['slug']+'/index.html',g['title'],g['description'],body,schema)
policies={
'about':('About Trailwise Gear','Practical outdoor information for people who care where their money goes.', [('Our purpose','Trailwise Gear is an independent publication operated by Jayden Ruiz. We help budget-conscious campers and outdoor enthusiasts compare equipment, prepare for trips, and avoid buying gear that does not solve a real problem.'),('What you will find','Our initial publication focuses on beginner car camping, complete cooking systems, and conservative vehicle-trip preparation. The first ten guides are desk-researched. They do not represent field tests or professional assessments of your equipment.'),('How the business works','We may earn commissions through disclosed affiliate links, including BougeRV, Nilight, KSP Performance, ALLPOWERS and Zenbivy links on the homepage, in relevant guides and on our Zenbivy collection page. A commercial relationship does not mean that we tested a product. Editorial recommendations include borrowing, reusing equipment, and delaying purchases when those options fit the reader better.'),('Accountability','Sources and evidence limits appear in each guide. Readers can report factual errors through our contact page. See the editorial policy for our research, AI assistance, and correction practices.')]),
'contact':('Contact & corrections','Send a question or report a factual error.', [('Public contact method','Use the public GitHub issue tracker linked below for editorial questions, broken links, and corrections. A GitHub account is required. This is a public channel: do not include an address, phone number, payment information, account credentials, or other private details.'),('What to include','Include the article URL, the claim or link in question, and a reliable source when possible. For a gear question, include the model and the use case without personal information. We review reports when operating the publication; no response time is guaranteed.'),('Partnership inquiries','Brands may use the same public channel for non-confidential partnership inquiries. We do not accept payment for undisclosed recommendations or fabricated reviews. Do not send confidential contracts or tax information through an issue.')]),
'editorial-policy':('Editorial & review policy','How we research, label evidence, and correct mistakes.', [('Research-based vs hands-on','Every initial guide is desk-researched. Manufacturer statements are attributed and do not become our measured results. A future hands-on review must identify the product version, conditions, method, and limitations. We will not imply that we used a product when we have not.'),('Sources and recommendations','We prioritize manufacturer documentation for specifications and compatibility, public land managers for access guidance, and authoritative safety sources for safety claims. Prices and availability change; we do not publish invented prices or claim real-time stock. We compare complete systems and distinguish editorial judgment from verified facts.'),('AI assistance','AI tools assist with research, writing, development, and maintenance. This does not constitute hands-on product testing or independent expert certification. We check important factual claims against linked sources and do not invent customer reviews, lab results, credentials, or affiliate relationships.'),('Commercial independence','We plan to use affiliate links only after program approval and receipt of real tracking information. A relationship will be disclosed near relevant links. We do not sell positive conclusions. Borrowing and not buying remain legitimate recommendations. No products were supplied for the initial guides.'),('Corrections and updates','Report errors through the contact page. Material corrections will be recorded in the affected article, with an updated date. Dates change when substantive review occurs, not automatically to imply freshness. Safety instructions and local rules must always be checked again before use.')]),
'affiliate-disclosure':('Affiliate disclosure','Our current monetization status and intended disclosure practice.', [('Current status','As of November 5, 2026, Trailwise Gear includes disclosed BougeRV, Nilight, KSP Performance, ALLPOWERS and Zenbivy affiliate links on the homepage, in relevant guides and on the Zenbivy collection page. We may earn a commission on qualifying purchases through those links, at no additional cost to you. Ordinary manufacturer and reference links are not affiliate links unless identified as such. No earnings are claimed.'),('Future affiliate links','We label affiliate recommendations near their links and may earn commissions on qualifying purchases. We update this disclosure when adding relationships. We will also follow each program’s required wording and linking rules.'),('Your choices','You are free to use our guides without buying anything. We aim to recommend equipment based on fit, evidence, and total cost. Commercial relationships do not establish that a product was tested or that it is the best option for everyone.')]),
'privacy':('Privacy notice','A plain-language description of this site’s current data practices.', [('Scope and current features','This notice describes the Trailwise Gear static website prepared on October 26, 2026. The site uses Cloudflare Web Analytics to measure page views and visits. Cloudflare states that Web Analytics does not track individual visitors using cookies or local storage. The site does not include newsletter forms, account systems, payment collection, or embedded videos. We do not measure affiliate clicks with our own site event system. When you click a disclosed affiliate link, the relevant affiliate network (including Impact, CJ or AvantLink) and the merchant can process referral information and may use cookies or similar technology under their own policies to attribute qualifying purchases.'),('Hosting and technical data','The site is served by Cloudflare. Requests necessarily expose technical information such as IP addresses and browser request headers to the hosting provider. Cloudflare may process security, operational, and diagnostic data under its own policies. We have not verified the account’s logging or retention settings, so we do not promise that hosting logs are absent or retained for a particular period.'),('External links and contact','External websites apply their own privacy practices. Our public contact method uses GitHub; information posted in an issue is public and GitHub processes account and usage data under its own policies. Do not post private or sensitive information. We have no private contact form on this website.'),('Changes and questions','If we add analytics, forms, advertising, or affiliate tracking, we will review and update this notice to describe the actual implementation. Use the contact page for privacy questions without sharing sensitive details publicly.')])}
for slug,(title,desc,sections) in policies.items():
    body=f'<div class="page-intro"><p class="eyebrow">THE PUBLICATION</p><h1>{e(title)}</h1><p>{e(desc)}</p></div><article class="prose policy">'+''.join(f'<section><h2>{e(h)}</h2><p>{e(t)}</p></section>' for h,t in sections)
    if slug=='contact':body+='<p><a class="button" href="https://github.com/JaydenRuiz669/trailwise-gear/issues">Open the public contact tracker →</a></p>'
    if slug=='privacy':body+='<p><a href="https://impact.com/privacy-policy/">Impact privacy policy</a> · <a href="https://www.avantlink.com/privacy-policy/">AvantLink privacy policy</a> · <a href="https://www.bougerv.com/pages/privacy-policy">BougeRV privacy policy</a></p>'
    if slug=='privacy':body+='<p><a href="https://www.cloudflare.com/privacypolicy/">Cloudflare privacy policy</a> · <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub privacy statement</a></p>'
    body+='</article>';page(slug+'/index.html',title,desc,body)
